package ru.ultimavox.itsm.servicedesk.application;
import java.time.Instant; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import ru.ultimavox.itsm.platform.audit.AuditTrail; import ru.ultimavox.itsm.platform.event.DomainEvent; import ru.ultimavox.itsm.platform.outbox.IntegrationEventOutbox;
@Service public class CreateWorkItem {
 private final JdbcTemplate jdbc; private final AuditTrail audit; private final IntegrationEventOutbox outbox;
 CreateWorkItem(JdbcTemplate jdbc,AuditTrail audit,IntegrationEventOutbox outbox){this.jdbc=jdbc;this.audit=audit;this.outbox=outbox;}
 @Transactional public Created create(Command c,String actor){ UUID id=UUID.randomUUID(), correlationId=UUID.randomUUID(); Instant now=Instant.now(); String prefix=c.type()==Type.INCIDENT?"INC":"REQ"; Long sequence=jdbc.queryForObject("SELECT nextval('work_item_number_seq')",Long.class); String number="%s-%06d".formatted(prefix,sequence); Map<String,Object> state=Map.of("number",number,"type",c.type().name(),"title",c.title(),"service",c.service(),"state","NEW","priority","MEDIUM"); jdbc.update("INSERT INTO work_item (id,number,type,title,description,service,state,priority,requester_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,number,c.type().name(),c.title(),c.description(),c.service(),"NEW","MEDIUM",actor,now,now); audit.append(new AuditTrail.Entry(actor,"work-item.created","work-item",id.toString(),Map.of(),state,correlationId,now)); outbox.record(new DomainEvent(UUID.randomUUID(),c.type()==Type.INCIDENT?"incident.created":"service-request.created",1,now,correlationId,"work-item",id.toString(),state)); return new Created(id,number,"NEW"); }
 public record Command(Type type,String title,String description,String service){} public record Created(UUID id,String number,String state){} public enum Type { INCIDENT, SERVICE_REQUEST }
}
